#include "wheel_effects.hpp"
#include <iostream>
#include <stdexcept>
using namespace ofo;
void need(bool b,const char*m){if(!b)throw std::runtime_error(m);}
int main(int argc,char**argv){try{
 WheelEffectConfig cfg;WheelSurface surface;surface.skid_type=3;surface.dirt_type=1;cfg.materials.push_back(surface);
 WheelEffects fx(cfg);std::array<WheelContact,4> c{};c[0].grounded=true;c[0].load=1000;c[0].material=0;c[0].width=.2f;c[0].speed=25;c[0].slip=7;c[0].velocity={0,0,25};
 fx.update(c,0);for(int i=1;i<30;i++){c[0].point.z+=.25f;fx.update(c,i*.02);}need(fx.particle_count()>0&&fx.skid_count()>0,"loaded slipping contact emits world particles and skids");auto n=fx.particle_count(),s=fx.skid_count();fx.update(c,.58);need(fx.particle_count()==n&&fx.skid_count()==s,"pause freezes effects");auto batches=fx.vertices({1,0,0},{0,1,0});need(!batches.skids.empty()&&!batches.particles.empty(),"renderable triangle batches");for(auto&v:batches.particles)need(v.u>=0&&v.u<=1&&v.v>=0&&v.v<=1,"native atlas bounded");
 fx.update(c,.1);need(fx.skid_count()==0&&fx.particle_count()==0,"backwards seek clears");c[0].point.z+=100;fx.update(c,.12);need(fx.skid_count()==0&&fx.particle_count()==0,"teleport clears");fx.clear();c[0].load=0;fx.update(c,0);for(int i=1;i<30;i++)fx.update(c,i*.02);need(!fx.particle_count()&&!fx.skid_count(),"zero load emits nothing");c[0].load=1000;c[0].grounded=false;for(int i=30;i<60;i++)fx.update(c,i*.02);need(!fx.particle_count()&&!fx.skid_count(),"airborne emits nothing");
 fx.clear();c[0].grounded=true;c[0].slip=0;c[0].lateral_speed=15;fx.update(c,0);for(int i=1;i<80;i++){c[0].point.x+=.2f;fx.update(c,i*.02);}need(fx.skid_count()>0,"lateral slide leaves skidmarks");for(int i=80;i<10000;i++){c[0].point.x+=.2f;fx.update(c,i*.02);}need(fx.skid_count()<=WheelEffects::max_skids&&fx.particle_count()<=WheelEffects::max_particles,"bounded persistent budgets");fx.update(c,200,1);need(!fx.skid_count()&&!fx.particle_count(),"recovery token clears");
 if(argc>1){Resources r(argv[1]);Geometry g;g.source="tracks/forest/forest1/track_geom.w32";for(auto name:{"road","grass","water","watertower","tarmac","water_pool"}){Material m;m.name=name;g.materials.push_back(m);}auto native=load_wheel_effect_config(r,g,"tracks/forest/forest1/a");need(native.loaded,"native particle parameters parsed");need(native.water_grow[0]==1.8f&&native.water_up[1]==8.5f,"native splash grow velocity");need(native.particle_texture=="tracks/forest/textures/particles.dds","family native atlas");need(native.skid_texture=="tracks/forest/textures/skidmark1.dds","family native skid atlas");need(native.dirt[1].life[0]==1.5f&&native.dirt[1].size[0]==.1f&&native.dirt[1].grow[0]==.2f,"native lifetime radius grow");need(native.materials[0].dirt_type==1&&native.materials[1].dirt_type==3,"material adapters choose native dirt types");need(native.materials[2].water&&!native.materials[3].water,"water tower excluded");need(native.materials[4].skid_type==3,"tarmac native skid type");need(native.materials[5].water,"water prefix shares renderer classification");}
 std::cout<<"wheel effects passed\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
